def _seed_existing_projects() -> None:
    """Give every existing project the ATCC v1 list it was implicitly on.

    Before this migration every project shared one hardcoded list, so a
    project with no rows of its own would suddenly have no classes at
    all - its existing annotations would point at ids that no longer
    resolve, and the review UI would offer nothing to label with.

    The preset is inlined rather than imported from app.core.presets on
    purpose: a migration has to keep describing the database as it was
    at this revision, and would otherwise silently change meaning the
    next time somebody edits that module.
    """
    atcc_v1 = [
        (1, "Two Wheeler"),
        (2, "Three-Wheeler Passenger"),
        (3, "Three-Wheeler Freight"),
        (4, "Car/Jeep/Van"),
        (5, "LCV 2-Axle"),
        (6, "LCV 3-Axle"),
        (7, "Bus 2-Axle"),
        (8, "Bus 3-Axle"),
        (9, "Mini-Bus"),
        (10, "Truck 2-Axle"),
        (11, "Truck 3-Axle"),
        (12, "Truck 4-Axle"),
        (13, "Truck 5-Axle"),
        (14, "Truck 6-Axle"),
        (15, "Truck Multi-Axle (7+)"),
        (16, "Earth Moving Machinery"),
        (17, "Heavy Construction Machinery"),
        (18, "Tractor"),
        (19, "Tractor with Trailer"),
        (20, "Tata Ace / similar mini LCV"),
    ]

    connection = op.get_bind()
    project_ids = [row[0] for row in connection.execute(sa.text("SELECT id FROM projects"))]
    if not project_ids:
        return

    now = datetime.now(timezone.utc)
    # Same list, new vocabulary: the column used to hold a schema
    # version ('v1') and now records which preset seeded the project.
    connection.execute(sa.text("UPDATE projects SET class_schema_version = 'atcc-v1' WHERE class_schema_version = 'v1'"))

    connection.execute(
        sa.text(
            "INSERT INTO class_definitions "
            "(id, project_id, class_id, name, display_order, created_at) "
            "VALUES (:id, :project_id, :class_id, :name, :display_order, :created_at)"
        ),
        [
            {
                "id": str(uuid.uuid4()),
                "project_id": project_id,
                "class_id": class_id,
                "name": name,
                "display_order": order,
                "created_at": now,
            }
            for project_id in project_ids
            for order, (class_id, name) in enumerate(atcc_v1)
        ],
    )


